SourceCode.Declaration:
public class TFMPageTypeAttribute extends SysAttribute implements SysExtensionIAttribute
{
    TFMPageType		pageType;
    str				label;

}

Method.Source:
void new(TFMPageType _pageType, str _label)
{
    super();

    pageType = _pageType;
    label = _label;
}

public TFMPageType parmPageType(TFMPageType _pageType = pageType)
{
    pageType = _pageType;

    return pageType;
}

public str parmLabel(str _label = label)
{
    label = _label;

    return label;
}
